        disabled={!canScrollNext} onClick={scrollNext} {...props}>
        <ArrowRight strokeWidth={3} />
        <span className="sr-only">Next slide</span>
      </PixelButton>
    );
  }
);
PixelCarouselNext.displayName = "PixelCarouselNext";

