"use client";

import * as React from "react";
import { CalendarIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import { PixelButton } from "./button";
import { PixelCalendar } from "./calendar";
import { PixelPopover, PixelPopoverContent, PixelPopoverTrigger } from "./popover";

interface PixelDatePickerProps {
  date?: Date;
  onDateChange?: (date: Date | undefined) => void;
  placeholder?: string;
  className?: string;
}

export function PixelDatePicker({ date, onDateChange, placeholder = "Pick a date", className }: PixelDatePickerProps) {
  const [open, setOpen] = React.useState(false);

  return (
    <PixelPopover open={open} onOpenChange={setOpen}>
      <PixelPopoverTrigger asChild>
        <PixelButton
          data-slot="date-picker-trigger"
          variant="outline"
          className={cn(
            "w-full justify-start text-left font-normal",
            !date && "text-muted-foreground",
            className
          )}
        >
          <CalendarIcon className="mr-2 h-4 w-4" strokeWidth={3} />
          {date ? date.toLocaleDateString() : <span>{placeholder}</span>}
        </PixelButton>
      </PixelPopoverTrigger>
      <PixelPopoverContent className="w-auto p-0" align="start">
        <PixelCalendar
          mode="single"
          selected={date}
          onSelect={(d) => { onDateChange?.(d); setOpen(false); }}
          initialFocus
        />
      </PixelPopoverContent>
    </PixelPopover>
  );
}

"use client";

import * as React from "react";
import * as RechartsPrimitive from "recharts";
import { cn } from "@/lib/utils";

const THEMES = { light: "", dark: ".dark" } as const;

export type ChartConfig = {
  [k in string]: {
    label?: React.ReactNode;
    icon?: React.ComponentType;
  } & ({ color?: string; theme?: never } | { color?: never; theme: Record<keyof typeof THEMES, string> });
};

type ChartContextProps = { config: ChartConfig };

const ChartContext = React.createContext<ChartContextProps | null>(null);

function useChart() {
  const context = React.useContext(ChartContext);
  if (!context) throw new Error("useChart must be used within a <ChartContainer />");
  return context;
}

function ChartContainer({
  id, className, children, config, ...props
}: React.ComponentProps<"div"> & { config: ChartConfig; children: React.ComponentProps<typeof RechartsPrimitive.ResponsiveContainer>["children"] }) {
  const uniqueId = React.useId();
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`;

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-video justify-center text-xs font-[family-name:var(--pixel-font)]",
          "[&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground",
          "[&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50",
          "[&_.recharts-curve.recharts-tooltip-cursor]:stroke-border",
          "[&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer>{children}</RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(([, config]) => config.theme || config.color);
  if (!colorConfig.length) return null;
  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES).map(([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig.map(([key, itemConfig]) => {
  const color = itemConfig.theme?.[theme as keyof typeof itemConfig.theme] || itemConfig.color;
  return color ? `  --color-${key}: ${color};` : null;
}).filter(Boolean).join("\n")}
}
`).join("\n"),
      }}
    />
  );
};

const ChartTooltip = RechartsPrimitive.Tooltip;

function ChartTooltipContent({
  active, payload, className, indicator = "dot", hideLabel = false, hideIndicator = false, label, labelFormatter, labelClassName, formatter, color, nameKey, labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> & React.ComponentProps<"div"> & {
  hideLabel?: boolean; hideIndicator?: boolean; indicator?: "line" | "dot" | "dashed";
  nameKey?: string; labelKey?: string;
}) {
  const { config } = useChart();
  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) return null;
    const [item] = payload;
    const key = `${labelKey || item.dataKey || item.name || "value"}`;
    const itemConfig = getPayloadConfigFromPayload(config, item, key);
    const value = !labelKey && typeof label === "string" ? config[label]?.label || label : itemConfig?.label;
    if (labelFormatter) return <div className={cn("text-xs", labelClassName)}>{labelFormatter(value, payload)}</div>;
    if (!value) return null;
    return <div className={cn("text-xs", labelClassName)}>{value}</div>;
  }, [label, labelFormatter, payload, hideLabel, labelClassName, config, labelKey]);

  if (!active || !payload?.length) return null;
  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div className={cn("border-2 border-foreground bg-popover px-2.5 py-1.5 text-xs shadow-[var(--pixel-shadow)]", className)}>
      {!nestLabel ? tooltipLabel : null}
      <div className="grid gap-1.5">
        {payload.filter((item) => item.type !== "none").map((item, index) => {
          const key = `${nameKey || item.name || item.dataKey || "value"}`;
          const itemConfig = getPayloadConfigFromPayload(config, item, key);
          const indicatorColor = color || item.payload.fill || item.color;
          return (
            <div key={item.dataKey} className={cn("flex w-full items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground", indicator === "dot" && "items-center")}>
              {formatter && item?.value !== undefined && item.name ? formatter(item.value, item.name, item, index, item.payload) : (
                <>
                  {itemConfig?.icon ? <itemConfig.icon /> : !hideIndicator && (
                    <div className={cn("shrink-0 border-2 border-foreground", { "h-2.5 w-2.5": indicator === "dot", "w-1": indicator === "line", "w-0 border-[1.5px] border-dashed bg-transparent": indicator === "dashed" })} style={{ "--color-bg": indicatorColor, "--color-border": indicatorColor } as React.CSSProperties} />
                  )}
                  <div className={cn("flex flex-1 justify-between leading-none", nestLabel ? "items-end" : "items-center")}>
                    <div className="grid gap-1.5">{nestLabel ? tooltipLabel : null}<span className="text-muted-foreground">{itemConfig?.label || item.name}</span></div>
                    {item.value && <span className="font-mono font-medium tabular-nums text-foreground">{item.value.toLocaleString()}</span>}
                  </div>
                </>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

const ChartLegend = RechartsPrimitive.Legend;

function ChartLegendContent({
  className, hideIcon = false, payload, verticalAlign = "bottom", nameKey,
}: React.ComponentProps<"div"> & Pick<RechartsPrimitive.LegendProps, "payload" | "verticalAlign"> & { hideIcon?: boolean; nameKey?: string }) {
  const { config } = useChart();
  if (!payload?.length) return null;
  return (
    <div className={cn("flex items-center justify-center gap-4", verticalAlign === "top" && "pb-3", className)}>
      {payload.filter((item) => item.type !== "none").map((item) => {
        const key = `${nameKey || item.dataKey || "value"}`;
        const itemConfig = getPayloadConfigFromPayload(config, item, key);
        return (
          <div key={item.value} className={cn("flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 text-muted-foreground")}>
            {itemConfig?.icon && !hideIcon ? <itemConfig.icon /> : !hideIcon && <div className="h-2 w-2 shrink-0 border-2 border-foreground" style={{ backgroundColor: item.color }} />}
            {itemConfig?.label}
          </div>
        );
      })}
    </div>
  );
}

function getPayloadConfigFromPayload(config: ChartConfig, payload: unknown, key: string) {
  if (typeof payload !== "object" || payload === null) return undefined;
  const payloadPayload = payload as { payload?: unknown; name?: string; dataKey?: string };
  const configLabelKey = key === "name" ? payloadPayload.name : payloadPayload.dataKey;
  return configLabelKey ? config[configLabelKey] : undefined;
}

export {
  ChartContainer, ChartTooltip, ChartTooltipContent, ChartLegend, ChartLegendContent, ChartStyle,
};

"use client";

import * as React from "react";
import { flexRender, type Table as TanstackTable, type ColumnDef } from "@tanstack/react-table";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { PixelButton } from "./button";
import { PixelSelect, PixelSelectContent, PixelSelectItem, PixelSelectTrigger, PixelSelectValue } from "./select";
import { PixelTable, PixelTableBody, PixelTableCell, PixelTableHead, PixelTableHeader, PixelTableRow } from "./table";

interface DataTableProps<TData, TValue> {
  table: TanstackTable<TData>;
  columns: ColumnDef<TData, TValue>[];
}

export function PixelDataTable<TData, TValue>({ table, columns }: DataTableProps<TData, TValue>) {
  return (
    <div data-slot="data-table" className="space-y-4 font-[family-name:var(--pixel-font)]">
      <PixelTable>
        <PixelTableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <PixelTableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <PixelTableHead key={header.id}>
                  {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                </PixelTableHead>
              ))}
            </PixelTableRow>
          ))}
        </PixelTableHeader>
        <PixelTableBody>
          {table.getRowModel().rows?.length ? (
            table.getRowModel().rows.map((row) => (
              <PixelTableRow key={row.id} data-state={row.getIsSelected() && "selected"}>
                {row.getVisibleCells().map((cell) => (
                  <PixelTableCell key={cell.id}>
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </PixelTableCell>
                ))}
              </PixelTableRow>
            ))
          ) : (
            <PixelTableRow>
              <PixelTableCell colSpan={columns.length} className="h-24 text-center">
                No results.
              </PixelTableCell>
            </PixelTableRow>
          )}
        </PixelTableBody>
      </PixelTable>

      <div className="flex items-center justify-between px-2">
        <div className="flex-1 text-xs text-muted-foreground">
          {table.getFilteredSelectedRowModel().rows.length} of {table.getFilteredRowModel().rows.length} row(s) selected.
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="text-xs">Rows per page</span>
            <PixelSelect
              value={`${table.getState().pagination.pageSize}`}
              onValueChange={(value) => table.setPageSize(Number(value))}
            >
              <PixelSelectTrigger className="h-8 w-[70px]">
                <PixelSelectValue placeholder={table.getState().pagination.pageSize} />
              </PixelSelectTrigger>
              <PixelSelectContent side="top">
                {[10, 20, 30, 40, 50].map((pageSize) => (
                  <PixelSelectItem key={pageSize} value={`${pageSize}`}>{pageSize}</PixelSelectItem>
                ))}
              </PixelSelectContent>
            </PixelSelect>
          </div>
          <div className="flex w-[100px] items-center justify-center text-xs">
            Page {table.getState().pagination.pageIndex + 1} of {table.getPageCount()}
          </div>
          <div className="flex items-center gap-1">
            <PixelButton
              variant="outline" size="icon" className="h-8 w-8"
              onClick={() => table.previousPage()}
              disabled={!table.getCanPreviousPage()}
            >
              <ChevronLeft className="h-4 w-4" strokeWidth={3} />
            </PixelButton>
            <PixelButton
              variant="outline" size="icon" className="h-8 w-8"
              onClick={() => table.nextPage()}
              disabled={!table.getCanNextPage()}
            >
              <ChevronRight className="h-4 w-4" strokeWidth={3} />
            </PixelButton>
          </div>
        </div>
      </div>
    </div>
  );
}

export type { ColumnDef };
